import{_ as r,o as t,c as s,a0 as o}from"./chunks/framework.B9sLprCo.js";const b=JSON.parse('{"title":"Inherited Cordis API","description":"","frontmatter":{"editSource":"docs/cordis-api/inherited.md"},"headers":[],"relativePath":"reference/cordis-api/inherited.md","filePath":"reference/cordis-api/inherited.md"}'),d={name:"reference/cordis-api/inherited.md"};function i(a,e,c,n,l,h){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="inherited-cordis-api" tabindex="-1">Inherited Cordis API <a class="header-anchor" href="#inherited-cordis-api" aria-label="Permalink to &quot;Inherited Cordis API&quot;">​</a></h1><p>The framework <code>ctx</code> members and events every plugin sees beyond the harness tier — pinned vendor source (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/README.md" target="_blank" rel="noreferrer">vendoring policy</a>), summarized tersely so the harness pages stay focused on repository-owned vocabulary. Detailed Context, Fiber, Registry, and Service APIs are generated in <a href="./context">context.md</a>, <a href="./fiber">fiber.md</a>, <a href="./registry">registry.md</a>, and <a href="./service">service.md</a>; the event-dispatch methods in <a href="./events">events.md</a>.</p><p>This file is GENERATED from source (<code>scripts/gen-cordis-catalog.ts</code>) and verified fresh by <code>pnpm run verify-cordis-catalog</code> — do not edit it by hand. Signature blocks use a <code>ts cordis-catalog</code> fence and include the original source JSDoc immediately before each event or service method. Type names in a signature link to the page that documents them.</p><h2 id="inherited-ctx-members-cordis-core-loader-hmr-timer" tabindex="-1">Inherited <code>ctx</code> members (cordis core + loader/hmr/timer) <a class="header-anchor" href="#inherited-ctx-members-cordis-core-loader-hmr-timer" aria-label="Permalink to &quot;Inherited `ctx` members (cordis core + loader/hmr/timer)&quot;">​</a></h2><ul><li><code>ctx.on / ctx.once</code> — Register an event listener (disposable). (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/cordis/src/events.ts" target="_blank" rel="noreferrer"><code>vendor/cordis/src/events.ts:34</code></a>)</li><li><code>ctx.emit / ctx.parallel / ctx.serial / ctx.bail / ctx.waterfall</code> — Dispatch an event (sync / awaited / first-bail / short-circuit chain). (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/cordis/src/events.ts" target="_blank" rel="noreferrer"><code>vendor/cordis/src/events.ts:34</code></a>)</li><li><code>ctx.plugin / ctx.inject</code> — Load a plugin / declare required services. (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/cordis/src/registry.ts" target="_blank" rel="noreferrer"><code>vendor/cordis/src/registry.ts:164</code></a>)</li><li><code>ctx.effect</code> — Register a disposable side effect tied to the fiber. (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/cordis/src/fiber.ts" target="_blank" rel="noreferrer"><code>vendor/cordis/src/fiber.ts:9</code></a>)</li><li><code>ctx.get / ctx.set / ctx.provide / ctx.accessor / ctx.mixin</code> — Low-level service-store access and binding. (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/cordis/src/reflect.ts" target="_blank" rel="noreferrer"><code>vendor/cordis/src/reflect.ts:7</code></a>)</li><li><code>ctx.extend / ctx.isolate / ctx.intercept</code> — Derive a child context (scoped services / isolation / interception). (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/cordis/src/context.ts" target="_blank" rel="noreferrer"><code>vendor/cordis/src/context.ts:42</code></a>)</li><li><code>ctx.root / ctx.scope / ctx.fiber / ctx.registry / ctx.reflect / ctx.events / ctx.logger</code> — Ambient handles onto the running context graph. (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/cordis/src/context.ts" target="_blank" rel="noreferrer"><code>vendor/cordis/src/context.ts:16</code></a>)</li><li><code>ctx.timer (+ interval / timeout / throttle / debounce)</code> — Disposable timer helpers. The <code>timer</code> key is provided at runtime; the four supported helpers are mixed onto ctx directly (declared via Pick). (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/timer/src/index.ts" target="_blank" rel="noreferrer"><code>vendor/timer/src/index.ts:4</code></a>)</li><li><code>ctx.loader</code> — The config Loader that booted the app (present under the loader). (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/loader/src/index.ts" target="_blank" rel="noreferrer"><code>vendor/loader/src/index.ts:30</code></a>)</li><li><code>ctx.hmr</code> — The hot-module-reload watcher (present under the hmr plugin). (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/hmr/src/index.ts" target="_blank" rel="noreferrer"><code>vendor/hmr/src/index.ts:15</code></a>)</li></ul><h2 id="inherited-events-cordis-core-loader-hmr-timer" tabindex="-1">Inherited events (cordis core + loader/hmr/timer) <a class="header-anchor" href="#inherited-events-cordis-core-loader-hmr-timer" aria-label="Permalink to &quot;Inherited events (cordis core + loader/hmr/timer)&quot;">​</a></h2><ul><li><code>internal/plugin</code> — A plugin fiber was created. (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/cordis/src/events.ts" target="_blank" rel="noreferrer"><code>vendor/cordis/src/events.ts:328</code></a>)</li><li><code>internal/status</code> — A fiber changed lifecycle state. (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/cordis/src/events.ts" target="_blank" rel="noreferrer"><code>vendor/cordis/src/events.ts:330</code></a>)</li><li><code>internal/service</code> — Interception hook for a service binding (no core producer). (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/cordis/src/events.ts" target="_blank" rel="noreferrer"><code>vendor/cordis/src/events.ts:332</code></a>)</li><li><code>internal/update</code> — Waterfall: a fiber config update is being applied. (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/cordis/src/events.ts" target="_blank" rel="noreferrer"><code>vendor/cordis/src/events.ts:334</code></a>)</li><li><code>internal/get</code> — Waterfall: a service is being read from the store. (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/cordis/src/events.ts" target="_blank" rel="noreferrer"><code>vendor/cordis/src/events.ts:336</code></a>)</li><li><code>internal/set</code> — Waterfall: a service is being written to the store. (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/cordis/src/events.ts" target="_blank" rel="noreferrer"><code>vendor/cordis/src/events.ts:338</code></a>)</li><li><code>internal/listener</code> — A listener was registered. (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/cordis/src/events.ts" target="_blank" rel="noreferrer"><code>vendor/cordis/src/events.ts:340</code></a>)</li><li><code>internal/dispatch</code> — An event is being dispatched to listeners. (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/cordis/src/events.ts" target="_blank" rel="noreferrer"><code>vendor/cordis/src/events.ts:342</code></a>)</li><li><code>hmr/change</code> — A watched source file changed on disk. (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/hmr/src/index.ts" target="_blank" rel="noreferrer"><code>vendor/hmr/src/index.ts:20</code></a>)</li><li><code>hmr/reload</code> — Plugins are being reloaded after a change. (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/hmr/src/index.ts" target="_blank" rel="noreferrer"><code>vendor/hmr/src/index.ts:21</code></a>)</li><li><code>exit</code> — The process is exiting on a signal. (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/loader/src/index.ts" target="_blank" rel="noreferrer"><code>vendor/loader/src/index.ts:23</code></a>)</li><li><code>loader/config-update</code> — The loader config tree changed. (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/loader/src/index.ts" target="_blank" rel="noreferrer"><code>vendor/loader/src/index.ts:24</code></a>)</li><li><code>loader/entry-init</code> — A config entry is being initialized. (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/loader/src/index.ts" target="_blank" rel="noreferrer"><code>vendor/loader/src/index.ts:25</code></a>)</li><li><code>loader/partial-dispose</code> — An entry is being partially disposed on reload. (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/loader/src/index.ts" target="_blank" rel="noreferrer"><code>vendor/loader/src/index.ts:26</code></a>)</li><li><code>loader/patch-context</code> — A context is being patched during a reload. (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/loader/src/index.ts" target="_blank" rel="noreferrer"><code>vendor/loader/src/index.ts:27</code></a>)</li></ul>',7)])])}const m=r(d,[["render",i]]);export{b as __pageData,m as default};
